package com.primehr.rewardsrecognition;
import com.primehr.rewardsrecognition.domain.*;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.*;import static org.assertj.core.api.Assertions.*;
class RrAwardDomainTest{
 @Test void correctionsAndRevocationsCreateImmutableSuccessorLineage(){var original=RrAwardRecord.confer("A","CASE","NOM","CYCLE","CAT","RR-2026-1","INDIVIDUAL","Ada","Service Award","Certificate","Citation",LocalDate.of(2026,12,1),"Approved decision","HEAD",Instant.now(),"fp");var correction=original.correct("Corrected certificate","Corrected citation",LocalDate.of(2026,12,1),"Correct spelling","HEAD",Instant.now(),"fp2");var revocation=correction.revoke("Decision reversed after due process","HEAD",Instant.now(),"fp3");assertThat(original.getRevisionNo()).isOne();assertThat(correction.getRevisionNo()).isEqualTo(2);assertThat(correction.getSupersedesAwardId()).isEqualTo(original.getId());assertThat(revocation.getRecordType()).isEqualTo(RrAwardRecord.RecordType.REVOCATION);assertThat(original.getPublicationCitation()).isEqualTo("Citation");assertThatThrownBy(()->revocation.correct("x","x",LocalDate.now(),"x","x",Instant.now(),"x")).isInstanceOf(IllegalStateException.class);}
 @Test void incentiveTypesAndFulfillmentEvidenceAreValidated(){assertThatThrownBy(()->new RrIncentiveAuthorization("A","AWARD",RrIncentiveAuthorization.Type.MONETARY,"Cash",BigDecimal.ZERO,"PHP","AUTH","EMP",Instant.now())).isInstanceOf(IllegalArgumentException.class);var monetary=new RrIncentiveAuthorization("A","AWARD",RrIncentiveAuthorization.Type.MONETARY,"Cash",new BigDecimal("1000"),"PHP","AUTH","EMP",Instant.now());assertThat(monetary.getAuthorizedAmount()).isEqualByComparingTo("1000.00");assertThatThrownBy(()->new RrFulfillmentEvent("A","AUTH",RrFulfillmentEvent.Status.FULFILLED,new BigDecimal("1000"),"Released",null,null,"EMP",Instant.now())).hasMessageContaining("evidence");var event=new RrFulfillmentEvent("A","AUTH",RrFulfillmentEvent.Status.FULFILLED,new BigDecimal("1000"),"Released","OR-1","0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef","EMP",Instant.now());assertThat(event.getStatus()).isEqualTo(RrFulfillmentEvent.Status.FULFILLED);}
}
